var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that ms("1y") returns approximately 31557600000 milliseconds
    // The original value should be around 31,557,600,000 (1 year in ms)
    // The changed version incorrectly returns d / 365.25, which is ~86,400,000 (1 day in ms)
    const result = ms('1y');
    assert.strictEqual(result, 31557600000, `Expected 31557600000ms for '1y', got ${result}`);
  });
});

